// Run: node scripts/brand-assets.mjs  (rebuilds every SVG in assets/ from the sources in assets/brand/)
//
// Sources, editable with scripts/brand-pixel-editor.html (import / export as JSON rows):
//   master-52.json  the 52-cell master: Scale2x of the 26-cell draft with the concave centre ('b' blue, 'w' bone)
//   draft-26.json   the 26-cell draft, used as is by the TUI splash and the 32 px favicon
//   cut-16.json     the hand-drawn 16-cell cut for 16 px favicons
//   outlines.json   outlined text (Cinzel, EB Garamond), regenerated by scripts/brand-outlines.py
import {readFileSync, writeFileSync} from 'node:fs';
import {join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const assets = join(root, 'assets');
const read = name => JSON.parse(readFileSync(join(assets, 'brand', name), 'utf8'));
const master = read('master-52.json'), draft = read('draft-26.json'), cut16 = read('cut-16.json'), outlines = read('outlines.json');

// Upper case = highlight, lower case = base, d/e = shadow.
const DARK = {B: '#97B5E8', b: '#7DA1DE', d: '#6688C8', W: '#F4F1EA', w: '#E8E4DA', e: '#CCC7BB'};       // on NIGHT
const LIGHT = {B: '#6487CF', b: '#4A6FBA', d: '#3A5CA3', W: '#46516A', w: '#2B3447', e: '#1D2432'};      // on PAPER
const NIGHT = '#121722', PAPER = '#F5F3EE', BONE = '#E8E4DA', INK = '#2B3447';
const mono = colour => Object.fromEntries([...'BbdWwe'].map(key => [key, colour]));

/** One-pixel rim light on edges facing the top left and shadow on edges facing the bottom right; then any tone pixel
 * without a same-tone neighbour goes back to the base colour, so light reads as edges, not dots on every stair step. */
function shade(grid) {
  const n = grid.length, at = (x, y) => grid[y]?.[x] ?? '.';
  const LIT = {b: 'B', w: 'W'}, DIM = {b: 'd', w: 'e'};
  const toned = grid.map((row, y) => [...row].map((c, x) => {
    if (c === '.') return c;
    const lit = (at(x - 1, y) !== c && at(x, y - 1) !== c) || (at(x - 1, y - 1) === '.' && (at(x - 1, y) !== c || at(x, y - 1) !== c));
    const dark = (at(x + 1, y) !== c && at(x, y + 1) !== c) || (at(x + 1, y + 1) === '.' && (at(x + 1, y) !== c || at(x, y + 1) !== c));
    return lit && !dark ? LIT[c] : dark && !lit ? DIM[c] : c;
  }));
  const base = {B: 'b', d: 'b', W: 'w', e: 'w'};
  return toned.map((row, y) => row.map((t, x) => {
    if (!base[t]) return t;
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) if ((dx || dy) && toned[y + dy]?.[x + dx] === t) return t;
    return base[t];
  }).join('')).slice(0, n);
}

/** Pixel rows as run-length rects. */
function pixels(rows, palette, x0 = 0, y0 = 0, cell = 1) {
  const out = [];
  rows.forEach((row, y) => {
    for (let start = 0, x = 1; x <= row.length; x++) {
      if (x < row.length && row[x] === row[start]) continue;
      if (row[start] !== '.') out.push(`<rect x="${+(x0 + start * cell).toFixed(2)}" y="${+(y0 + y * cell).toFixed(2)}" width="${+((x - start) * cell).toFixed(2)}" height="${+cell.toFixed(2)}" fill="${palette[row[start]]}"/>`);
      start = x;
    }
  });
  return `<g shape-rendering="crispEdges">${out.join('')}</g>`;
}

/** Outlined text at `size` (font units scaled), left edge x, baseline y. Returns [svg, advance]. */
function text(face, value, size, x, y, fill, tracking = 0) {
  const k = size / face.upm, parts = [];
  let pen = 0;
  for (const ch of value) {
    const glyph = face.glyphs[ch];
    if (!glyph) throw new Error(`outlines.json has no glyph for ${JSON.stringify(ch)}; rerun scripts/brand-outlines.py`);
    if (glyph.d) parts.push(`<path transform="matrix(${k} 0 0 ${-k} ${+(x + pen).toFixed(2)} ${+y.toFixed(2)})" d="${glyph.d}"/>`);
    pen += glyph.advance * k + tracking * size;
  }
  return [`<g fill="${fill}">${parts.join('')}</g>`, pen - tracking * size];
}

/** The master's centre (ring and core), cropped: it stands in for the wordmark's second O. */
function core() {
  const c = master.length / 2;
  const kept = master.map((row, y) => [...row].map((p, x) => Math.abs(x + 0.5 - c) + Math.abs(y + 0.5 - c) <= 12.5 ? p : '.').join(''));
  const live = kept.filter(row => row.replace(/\./g, ''));
  const left = Math.min(...live.map(row => row.search(/[^.]/))), right = Math.max(...live.map(row => row.replace(/\.+$/, '').length));
  return live.map(row => row.slice(left, right));
}

/** LOG, the pixel core, X: cap height 100, baseline y=100. Returns [svg, width]. */
function wordmark(ink, palette) {
  const face = outlines.wordmark, size = face.upm * 100 / face.capHeight, track = 0.12 * size;
  let x = 0;
  const parts = [];
  for (const ch of 'LOG') { const [svg, w] = text(face, ch, size, x, 100, ink); parts.push(svg); x += w + track; }
  const crop = core(), height = 94, cell = height / crop.length, oWidth = face.glyphs.O.advance * size / face.upm;
  parts.push(pixels(crop, palette, x + (oWidth - crop[0].length * cell) / 2, (100 - height) / 2, cell));
  x += oWidth + track;
  const [svg, w] = text(face, 'X', size, x, 100, ink);
  parts.push(svg);
  return [parts.join(''), x + w];
}

function banner(palette, bg, ink, muted, rule) {
  const W = 1280, H = 400, left = 492;
  const [word, width] = wordmark(ink, palette), s = Math.min(1, (W - left - 84) / width), top = (H - (100 * s + 114)) / 2;
  const [tagline] = text(outlines.tagline, outlines.tagline.text, 34, left, top + 100 * s + 58, ink);
  const [subtitle] = text(outlines.subtitle, outlines.subtitle.text, 21, left, top + 100 * s + 114, muted, 0.06);
  return [`<rect width="${W}" height="${H}" rx="22" fill="${bg}"/>${pixels(shade(master), palette, 92, (H - 52 * 6) / 2, 6)}`
    + `<g transform="translate(${left} ${top.toFixed(1)}) scale(${s.toFixed(4)})">${word}</g>${tagline}`
    + `<line x1="${left}" y1="${(top + 100 * s + 80).toFixed(1)}" x2="${(left + width * s).toFixed(1)}" y2="${(top + 100 * s + 80).toFixed(1)}" stroke="${rule}"/>${subtitle}`, W, H];
}

function lockup(palette, ink) {
  const cell = 5, size = 52 * cell, gap = 64, [word, width] = wordmark(ink, palette);
  return [pixels(shade(master), palette, 0, 0, cell) + `<g transform="translate(${size + gap} ${(size - 100) / 2})">${word}</g>`, size + gap + width, size];
}

const files = {};
const svg = (name, title, body, w, h, scale = 1) => {
  files[name] = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${+w.toFixed(2)} ${+h.toFixed(2)}" width="${+(w * scale).toFixed(2)}" height="${+(h * scale).toFixed(2)}" role="img" aria-label="${title}"><title>${title}</title>${body}</svg>\n`;
};
const shaded = shade(master);
svg('logo-mark.svg', 'LOGOX', pixels(shaded, DARK), 52, 52, 8);
svg('logo-mark-light.svg', 'LOGOX', pixels(shaded, LIGHT), 52, 52, 8);
svg('logo-mark-mono.svg', 'LOGOX', pixels(master, mono(NIGHT)), 52, 52, 8);
svg('logo-mark-reversed.svg', 'LOGOX', pixels(master, mono(BONE)), 52, 52, 8);
svg('logo-mark-16.svg', 'LOGOX', pixels(cut16, DARK), 16, 16, 2);
svg('logo-mark-16-light.svg', 'LOGOX', pixels(cut16, LIGHT), 16, 16, 2);
svg('app-icon.svg', 'LOGOX', `<rect width="64" height="64" rx="14" fill="${NIGHT}"/>${pixels(shaded, DARK, 6, 6)}`, 64, 64, 8);
svg('favicon.svg', 'LOGOX', `<rect width="18" height="18" rx="4" fill="${NIGHT}"/>${pixels(cut16, DARK, 1, 1)}`, 18, 18);
svg('favicon-32.svg', 'LOGOX', `<rect width="32" height="32" rx="7" fill="${NIGHT}"/>${pixels(draft, DARK, 3, 3)}`, 32, 32);
for (const [name, palette, ink] of [['wordmark.svg', DARK, BONE], ['wordmark-light.svg', LIGHT, INK]]) {
  const [body, w] = wordmark(ink, palette);
  svg(name, 'LOGOX', `<g transform="translate(0 4)">${body}</g>`, w, 108);
}
for (const [name, palette, ink] of [['logo.svg', DARK, BONE], ['logo-light.svg', LIGHT, INK]]) svg(name, 'LOGOX', ...lockup(palette, ink));
svg('banner.svg', 'LOGOX: A terminal coding ensemble', ...banner(DARK, NIGHT, BONE, '#8E97A8', '#2A3446'));
svg('banner-light.svg', 'LOGOX: A terminal coding ensemble', ...banner(LIGHT, PAPER, INK, '#6B7385', '#D9D5CB'));
for (const [name, content] of Object.entries(files)) writeFileSync(join(assets, name), content);
console.log(`wrote ${Object.keys(files).length} files to assets/`);
